window.CIVIL_SET_DATA["past-05"] = {"title":"Past Paper Set 5","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-05-003","src":"PAST-05-003","text":"The centre of gravity of a hemisphere is at","options":[{"key":"a","text":"\\(\\dfrac{3r}{8}\\)"},{"key":"b","text":"\\(\\dfrac{4r}{5\\pi}\\)"},{"key":"c","text":"\\(\\dfrac{3r}{4}\\)"},{"key":"d","text":"\\(\\dfrac{4r}{3\\pi}\\)"}],"answer":"a","explanation":"The centroid of a solid hemisphere lies 3r/8 from its flat face. 4r/3π is the centroid of a semicircular area.","marks":1,"source":{"kind":"past","set":5,"question":3,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q3 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-05-018","src":"PAST-05-018","text":"Lacquer is","options":[{"key":"a","text":"Oil paints"},{"key":"b","text":"Distemper"},{"key":"c","text":"Spirit varnish"},{"key":"d","text":"Enamel paints"}],"answer":"c","explanation":"Lacquer is a spirit varnish: a resin (such as shellac) dissolved in a volatile spirit that dries quickly by evaporation to a hard glossy film.","marks":1,"source":{"kind":"past","set":5,"question":18,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q18 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-05-039","src":"PAST-05-039","text":"Which of the following is an obstacle to chaining but not to ranging?","options":[{"key":"a","text":"Building"},{"key":"b","text":"Hillock"},{"key":"c","text":"River"},{"key":"d","text":"All of these"}],"answer":"c","explanation":"Across a river the end stations can still be seen, so ranging is possible, but the tape cannot be stretched. A building obstructs both, and over a hillock ranging is obstructed while chaining is still possible.","marks":1,"source":{"kind":"past","set":5,"question":39,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q39 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-05-050","src":"PAST-05-050","text":"Seasoning of timber is done","options":[{"key":"a","text":"to make it water proof"},{"key":"b","text":"to paint its surface"},{"key":"c","text":"to increase its temperature"},{"key":"d","text":"to remove water"}],"answer":"d","explanation":"Seasoning reduces the moisture (sap) content of timber to about its equilibrium value. This improves strength and durability and prevents shrinkage, warping and decay.","marks":1,"source":{"kind":"past","set":5,"question":50,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q50 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-05-054","src":"PAST-05-054","text":"With a percentage increase of carbon in steel, it decreases its","options":[{"key":"a","text":"strength"},{"key":"b","text":"hardness"},{"key":"c","text":"brittleness"},{"key":"d","text":"ductility"}],"answer":"d","explanation":"Raising the carbon content increases strength, hardness and brittleness but reduces ductility and weldability.","marks":1,"source":{"kind":"past","set":5,"question":54,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q54 · 1 mark"},"topic":"ACiE0101"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-05-008","src":"PAST-05-008","text":"The gross area of a footing is dependent on","options":[{"key":"a","text":"Load from superstructure"},{"key":"b","text":"Bearing capacity of soil"},{"key":"c","text":"Type of soil"},{"key":"d","text":"All of these"}],"answer":"d","explanation":"The footing area is the total load divided by the allowable bearing pressure, \\[A = \\dfrac{P}{q_a}\\] The load comes from the superstructure, and the allowable pressure depends on the type and bearing capacity of the soil.","marks":1,"source":{"kind":"past","set":5,"question":8,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q8 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-05-009","src":"PAST-05-009","text":"The depth of exploration is independent of","options":[{"key":"a","text":"Size of structure"},{"key":"b","text":"Type of structure"},{"key":"c","text":"Type of boring"},{"key":"d","text":"Load of structure"}],"answer":"c","explanation":"The exploration depth is fixed by the depth of significant stress (about 1.5–2 times the footing width, or down to a firm stratum), which depends on the structure's size, type and loads. The boring method only obtains the samples.","marks":1,"source":{"kind":"past","set":5,"question":9,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q9 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-05-044","src":"PAST-05-044","text":"A mat is a type of","options":[{"key":"a","text":"Shallow foundation"},{"key":"b","text":"Deep foundation"},{"key":"c","text":"Both"},{"key":"d","text":"None of the above"}],"answer":"a","explanation":"A mat (raft) is a single slab carrying all the columns at shallow depth (D<sub>f</sub> ≤ B). It is used where the soil is weak or the footings would overlap.","marks":1,"source":{"kind":"past","set":5,"question":44,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q44 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-05-045","src":"PAST-05-045","text":"The factor of safety for an infinite slope with steady seepage is","options":[{"key":"a","text":"More than dry slope"},{"key":"b","text":"Equal to dry slope"},{"key":"c","text":"Approx. half of the dry slope"},{"key":"d","text":"None of the above"}],"answer":"c","explanation":"For a cohesionless infinite slope, \\[\\text{FS}_{dry} = \\dfrac{\\tan\\phi}{\\tan\\beta}\\] \\[\\text{FS}_{seep} = \\dfrac{\\gamma'}{\\gamma_{sat}}\\dfrac{\\tan\\phi}{\\tan\\beta}\\] with seepage parallel to the slope. Since \\(\\dfrac{\\gamma'}{\\gamma_{sat}} \\approx 0.5\\), seepage roughly halves the factor of safety.","marks":1,"source":{"kind":"past","set":5,"question":45,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q45 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-05-046","src":"PAST-05-046","text":"The bearing capacity of a square footing is","options":[{"key":"a","text":"\\(Q_u = cN_c\\) \\(+\\,\\gamma DN_q\\) \\(+\\,0.5\\gamma BN_\\gamma\\)"},{"key":"b","text":"\\(Q_u = 1.3cN_c\\) \\(+\\,\\gamma DN_q\\) \\(+\\,0.4\\gamma BN_\\gamma\\)"},{"key":"c","text":"\\(Q_u = 1.3cN_c\\) \\(+\\,\\gamma DN_q\\) \\(+\\,0.3\\gamma BN_\\gamma\\)"},{"key":"d","text":"\\(Q_u = 1.3cN_c\\) \\(+\\,\\gamma DN_q\\) \\(+\\,0.5\\gamma BN_\\gamma\\)"}],"answer":"b","explanation":"Terzaghi's shape factors for a square footing are 1.3 on the cohesion term and 0.4 on the width term, so \\[\\begin{aligned} q_u &amp;= 1.3cN_c + \\gamma DN_q \\\\ &amp;\\quad + 0.4\\gamma BN_\\gamma \\end{aligned}\\] A circular footing uses \\(0.3\\gamma BN_\\gamma\\).","marks":1,"source":{"kind":"past","set":5,"question":46,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q46 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-05-051","src":"PAST-05-051","text":"The ratio of the volume of water present in a given soil mass to the total volume of its voids is known as","options":[{"key":"a","text":"porosity"},{"key":"b","text":"void ratio"},{"key":"c","text":"percentage voids"},{"key":"d","text":"degree of saturation"}],"answer":"d","explanation":"The degree of saturation is \\[S = \\dfrac{V_w}{V_v}\\] Porosity is \\(\\dfrac{V_v}{V}\\) and void ratio is \\(\\dfrac{V_v}{V_s}\\).","marks":1,"source":{"kind":"past","set":5,"question":51,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q51 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-05-064","src":"PAST-05-064","text":"What is the formula for shear strength from the vane shear test?","options":[{"key":"a","text":"\\(S = \\dfrac{T}{\\pi D^2\\left(\\tfrac{H}{2} + \\tfrac{D}{3}\\right)}\\)"},{"key":"b","text":"\\(S = \\dfrac{T}{\\pi D^2\\left(\\tfrac{H}{2} + \\tfrac{D}{6}\\right)}\\)"},{"key":"c","text":"\\(S = \\dfrac{T}{\\pi D^2\\left(\\tfrac{H}{4} + \\tfrac{D}{6}\\right)}\\)"},{"key":"d","text":"\\(S = \\dfrac{T}{\\pi D^2\\left(\\tfrac{H}{4} + \\tfrac{D}{3}\\right)}\\)"}],"answer":"b","explanation":"With both the top and bottom ends shearing, \\[T = S\\pi D^2\\left(\\dfrac{H}{2} + \\dfrac{D}{6}\\right)\\] With only the bottom end shearing, the end term becomes \\(\\dfrac{D}{12}\\).","marks":2,"source":{"kind":"past","set":5,"question":64,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q64 · 2 marks"},"topic":"ACiE0203"},{"id":"PAST-05-078","src":"PAST-05-078","text":"The weight of a pycnometer containing 400 g sand and water full to the top is 2150 g. The weight of the pycnometer full of clean water is 1950 g. If the specific gravity of the soil is 2.5, the water content is","options":[{"key":"a","text":"5%"},{"key":"b","text":"10%"},{"key":"c","text":"15%"},{"key":"d","text":"20%"}],"answer":"d","explanation":"The pycnometer relation gives, as a fraction, \\[w = \\dfrac{W_2 - W_1}{W_3 - W_4} \\times \\dfrac{G - 1}{G} - 1\\] so \\[\\begin{aligned} w &amp;= \\dfrac{400}{200} \\times \\dfrac{1.5}{2.5} - 1 \\\\ &amp;= 1.2 - 1 = 0.20 = 20\\% \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":5,"question":78,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q78 · 2 marks"},"topic":"ACiE0201"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-05-004","src":"PAST-05-004","text":"The Froude number of a triangular channel of depth \\(y\\) with side slope 2H:1V is","options":[{"key":"a","text":"\\(\\dfrac{V}{\\sqrt{gy/4}}\\)"},{"key":"b","text":"\\(\\dfrac{V}{\\sqrt{gy/2}}\\)"},{"key":"c","text":"\\(\\dfrac{V}{\\sqrt{gy}}\\)"},{"key":"d","text":"\\(\\dfrac{V}{\\sqrt{gy/3}}\\)"}],"answer":"b","explanation":"The Froude number uses the hydraulic depth: \\[\\text{Fr} = \\dfrac{V}{\\sqrt{gD}}, \\qquad D = \\dfrac{A}{T}\\] For side slopes 2H:1V, \\(A = 2y^2\\) and \\(T = 4y\\), so \\(D = \\dfrac{y}{2}\\).","marks":1,"source":{"kind":"past","set":5,"question":4,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q4 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-05-005","src":"PAST-05-005","text":"Which of the following statements is correct about the stream length of fan-shaped and fern-shaped catchments?","options":[{"key":"a","text":"Stream length of fan shaped catchment is more"},{"key":"b","text":"Stream length of fern shaped catchment is more"},{"key":"c","text":"Stream length of both catchments is same"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"A fern-shaped (elongated) catchment has a long main stream with short tributaries joining along it. A fan-shaped catchment has short streams converging near the outlet, which also gives it a sharper, earlier flood peak.","marks":1,"source":{"kind":"past","set":5,"question":5,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q5 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-05-011","src":"PAST-05-011","text":"What is the value of pressure inside a soap bubble having radius \\(R\\)?","options":[{"key":"a","text":"\\(\\dfrac{8T}{R}\\)"},{"key":"b","text":"\\(\\dfrac{4T}{R}\\)"},{"key":"c","text":"\\(\\dfrac{2T}{R}\\)"},{"key":"d","text":"\\(\\dfrac{T}{R}\\)"}],"answer":"b","explanation":"A soap bubble has two free surfaces, so \\[\\Delta p = 2 \\times \\dfrac{2T}{R} = \\dfrac{4T}{R} = \\dfrac{8T}{d}\\] A liquid drop, with one surface, has \\(\\dfrac{2T}{R}\\).","marks":1,"source":{"kind":"past","set":5,"question":11,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q11 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-05-015","src":"PAST-05-015","text":"Water is flowing down steadily in a constant cross-sectional pipe. According to the Bernoulli principle","options":[{"key":"a","text":"Pressure increases with height"},{"key":"b","text":"Pressure decreases with height"},{"key":"c","text":"Velocity increases with height"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"With a constant area the velocity head is constant, so \\[\\dfrac{p}{\\gamma} + z = \\text{constant}\\] Pressure falls as elevation rises (and rises as the water flows down).","marks":1,"source":{"kind":"past","set":5,"question":15,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q15 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-05-017","src":"PAST-05-017","text":"Which method gives accurate flow characteristics in the context of rivers of Nepal?","options":[{"key":"a","text":"WECS/DHM 1990"},{"key":"b","text":"MIP"},{"key":"c","text":"DHM 2004"},{"key":"d","text":"None of these"}],"answer":"c","explanation":"The DHM (2004) regional method was derived from a longer and larger set of gauged Nepali records. It generally gives better estimates of flow characteristics for ungauged rivers than the older WECS/DHM (1990) and MIP methods.","marks":1,"source":{"kind":"past","set":5,"question":17,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q17 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-05-052","src":"PAST-05-052","text":"Which of the following statements is correct about the shear stress distribution in circular pipes with laminar flow?","options":[{"key":"a","text":"It is linear with maximum value at the centre"},{"key":"b","text":"It is parabolic with maximum value at the centre"},{"key":"c","text":"It is parabolic with zero value at the centre"},{"key":"d","text":"It is linear with zero value at the centre"}],"answer":"d","explanation":"In laminar pipe flow \\[\\tau = \\left(-\\dfrac{dp}{dx}\\right)\\dfrac{r}{2}\\] which varies linearly from zero at the centre to its maximum at the wall. The velocity profile is parabolic.","marks":1,"source":{"kind":"past","set":5,"question":52,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q52 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-05-065","src":"PAST-05-065","text":"If the depression in a glass tube of 1.2 mm diameter immersed in mercury is 8 mm, find the diameter of the tube to have a depression of 4 mm.","options":[{"key":"a","text":"1.2 mm"},{"key":"b","text":"2.4 mm"},{"key":"c","text":"3.6 mm"},{"key":"d","text":"4.8 mm"}],"answer":"b","explanation":"Capillary rise or depression is \\[h = \\dfrac{4\\sigma\\cos\\theta}{\\rho gd} \\propto \\dfrac{1}{d}\\] Halving the depression to 4 mm needs twice the diameter, 2.4 mm.","marks":2,"source":{"kind":"past","set":5,"question":65,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q65 · 2 marks"},"topic":"ACiE0301"},{"id":"PAST-05-066","src":"PAST-05-066","text":"The velocity of propagation of water hammer pressure in a pipe carrying water and having diameter = 40 cm, pipe thickness = 4 mm, with \\(E\\) (modulus of elasticity) of the pipe material = 2.1×10<sup>11</sup> Pa and \\(K\\) (bulk modulus of water) = 2.1×10<sup>9</sup> Pa, is","options":[{"key":"a","text":"1400 m/s"},{"key":"b","text":"2000 m/s"},{"key":"c","text":"1000 m/s"},{"key":"d","text":"700 m/s"}],"answer":"c","explanation":"The wave speed in an elastic pipe is \\[C = \\dfrac{\\sqrt{K{/}\\rho}}{\\sqrt{1 + \\dfrac{KD}{Et}}}\\] Here \\(\\sqrt{K{/}\\rho} = 1449\\) m per s and \\[\\begin{aligned} \\dfrac{KD}{Et} &amp;= \\dfrac{2.1 \\times 10^9 \\times 0.4}{2.1 \\times 10^{11} \\times 0.004} \\\\ &amp;= 1 \\end{aligned}\\] so \\[C = \\dfrac{1449}{\\sqrt{2}} \\approx 1025 \\approx 1000\\] metres per second.","marks":2,"source":{"kind":"past","set":5,"question":66,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q66 · 2 marks"},"topic":"ACiE0304"},{"id":"PAST-05-067","src":"PAST-05-067","text":"A rectangular surface 2.5 m × 3 m is immersed vertically in water touching its surface. Find the depth of the centre of pressure.","options":[{"key":"a","text":"1 m"},{"key":"b","text":"1.5 m"},{"key":"c","text":"2 m"},{"key":"d","text":"1.25 m"}],"answer":"c","explanation":"For a vertical rectangle with its top edge at the surface, the centre of pressure is at two-thirds of the depth (taking the 3 m side vertical): \\[h_p = \\dfrac{2}{3} \\times 3 = 2\\ \\text{m}\\]","marks":2,"source":{"kind":"past","set":5,"question":67,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q67 · 2 marks"},"topic":"ACiE0302"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-05-007","src":"PAST-05-007","text":"A train of wheel loads is moving over a simply supported beam. The shear force will be maximum at support A when","options":[{"key":"a","text":"Trail load is at A"},{"key":"b","text":"Leading load is at A"},{"key":"c","text":"Load is at mid span"},{"key":"d","text":"Shear force will be equal in all cases"}],"answer":"a","explanation":"The shear at A equals the reaction R<sub>A</sub>, which is greatest when the whole train is on the span as close to A as possible, i.e. with the end load of the train at A. For a train entering from A this is the trailing load, as the key states.","marks":1,"source":{"kind":"past","set":5,"question":7,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q7 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-05-010","src":"PAST-05-010","text":"In a simply supported beam, two equal point loads P act at a distance of L/3 from both supports A and B. What is the value of shear force at a distance L/6 from support A?","options":[{"key":"a","text":"P"},{"key":"b","text":"2P"},{"key":"c","text":"P/3"},{"key":"d","text":"P/6"}],"answer":"a","explanation":"By symmetry \\(R_A = R_B = P\\). At \\(\\dfrac{L}{6}\\) there is no load between A and the section, so the shear force equals \\(R_A = P\\).","marks":1,"source":{"kind":"past","set":5,"question":10,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q10 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-05-028","src":"PAST-05-028","text":"For a two-hinged arch having constant \\(EI\\), the horizontal thrust \\(H\\) at a point \\((x, y)\\) on the arch, in terms of beam moment \\(M\\), is given by","options":[{"key":"a","text":"\\(\\dfrac{\\int My\\,ds/EI}{\\int y^3\\,ds/EI}\\)"},{"key":"b","text":"\\(\\dfrac{\\int My\\,ds/EI}{\\int y\\,ds/EI}\\)"},{"key":"c","text":"\\(\\dfrac{\\int My^2\\,ds/EI}{\\int y^2\\,ds/EI}\\)"},{"key":"d","text":"\\(\\dfrac{\\int My\\,ds/EI}{\\int y^2\\,ds/EI}\\)"}],"answer":"d","explanation":"Zero relative horizontal movement of the supports (Castigliano) gives \\[H = \\dfrac{\\displaystyle\\int \\dfrac{My\\,ds}{EI}}{\\displaystyle\\int \\dfrac{y^2\\,ds}{EI}}\\] where \\(M\\) is the free beam moment. (The paper prints the numerator increment as dy over dx; ds over EI is intended.)","marks":1,"source":{"kind":"past","set":5,"question":28,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q28 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-05-047","src":"PAST-05-047","text":"Virtual work refers to","options":[{"key":"a","text":"Virtual work done by virtual forces"},{"key":"b","text":"Virtual work done by actual forces"},{"key":"c","text":"Actual work done by actual forces"},{"key":"d","text":"Actual work done by virtual forces"}],"answer":"b","explanation":"Virtual work is the work done by the real (actual) forces moving through a virtual (imaginary, compatible) displacement. The complementary form uses virtual forces moving through real displacements.","marks":1,"source":{"kind":"past","set":5,"question":47,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q47 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-05-048","src":"PAST-05-048","text":"The deflection at the centre of a fixed beam with total load \\(W\\) applied uniformly over its length \\(L\\) is","options":[{"key":"a","text":"\\(\\dfrac{WL^4}{384EI}\\)"},{"key":"b","text":"\\(\\dfrac{WL^3}{384EI}\\)"},{"key":"c","text":"\\(\\dfrac{WL^4}{192EI}\\)"},{"key":"d","text":"\\(\\dfrac{WL^3}{192EI}\\)"}],"answer":"b","explanation":"For a fixed beam \\[\\delta = \\dfrac{wL^4}{384EI}\\] With the total load \\(W = wL\\) this becomes \\[\\delta = \\dfrac{WL^3}{384EI}\\] one-fifth of the simply supported value.","marks":1,"source":{"kind":"past","set":5,"question":48,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q48 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-05-053","src":"PAST-05-053","text":"In influence line diagrams (ILD)","options":[{"key":"a","text":"Points remain fixed, position of load changes"},{"key":"b","text":"Points change, position of loads remain fixed"},{"key":"c","text":"Both of them change"},{"key":"d","text":"Neither of them changes"}],"answer":"a","explanation":"An influence line shows how a response at a fixed point (reaction, shear or moment) varies as a unit load moves across the structure.","marks":1,"source":{"kind":"past","set":5,"question":53,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q53 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-05-062","src":"PAST-05-062","text":"In a three hinged symmetric semicircular arch of span 40 m and central rise 8 m, an 80 kN point load is acting at a distance of 6 m from support A. Determine the horizontal thrust.","options":[{"key":"a","text":"30 kN"},{"key":"b","text":"100 kN"},{"key":"c","text":"120 kN"},{"key":"d","text":"140 kN"}],"answer":"a","explanation":"The right support reaction is \\[V_B = \\dfrac{80 \\times 6}{40} = 12\\ \\text{kN}\\] Taking moments about the crown hinge for the right half, \\[H \\times 8 = 12 \\times 20\\] so \\(H = 30\\) kN.","marks":2,"source":{"kind":"past","set":5,"question":62,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q62 · 2 marks"},"topic":"ACiE0405"},{"id":"PAST-05-069","src":"PAST-05-069","text":"A column of length \\(L\\) is fixed at both ends. It is equivalent to another column with both ends hinged having length ……","options":[{"key":"a","text":"\\(L\\)"},{"key":"b","text":"\\(2L\\)"},{"key":"c","text":"\\(\\dfrac{L}{2}\\)"},{"key":"d","text":"\\(\\dfrac{L}{\\sqrt{2}}\\)"}],"answer":"c","explanation":"A column fixed at both ends has effective length L/2 (theoretical), so it behaves like a pin-ended column of length L/2 and carries four times the load.","marks":2,"source":{"kind":"past","set":5,"question":69,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q69 · 2 marks"},"topic":"ACiE0403"}]},{"name":"Design of Structures","questions":[{"id":"PAST-05-002","src":"PAST-05-002","text":"The \\(S/d\\) ratio of a solid circular timber column should not exceed","options":[{"key":"a","text":"25"},{"key":"b","text":"50"},{"key":"c","text":"75"},{"key":"d","text":"100"}],"answer":"b","explanation":"IS 883 limits the slenderness ratio (unsupported length / least dimension) of solid timber columns to 50.","marks":1,"source":{"kind":"past","set":5,"question":2,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q2 · 1 mark"},"topic":"ACiE0506"},{"id":"PAST-05-027","src":"PAST-05-027","text":"Bulking of coarse aggregate is","options":[{"key":"a","text":"More than sand"},{"key":"b","text":"less than sand"},{"key":"c","text":"negligible"},{"key":"d","text":"equal to sand"}],"answer":"c","explanation":"The water films that cause bulking are significant only between fine grains. Coarse aggregate has so little surface area per unit volume that its bulking is negligible.","marks":1,"source":{"kind":"past","set":5,"question":27,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q27 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-05-038","src":"PAST-05-038","text":"The vertical formwork of a column can be removed after","options":[{"key":"a","text":"24 hr"},{"key":"b","text":"3 days"},{"key":"c","text":"7 days"},{"key":"d","text":"10 days"}],"answer":"a","explanation":"IS 456 allows vertical faces of columns, walls and beams to be struck after 16–24 hours with OPC. Beam soffits need 7 days (props 14–21 days).","marks":1,"source":{"kind":"past","set":5,"question":38,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q38 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-05-041","src":"PAST-05-041","text":"Water to be used in concrete is similar to","options":[{"key":"a","text":"Distilled"},{"key":"b","text":"Potable"},{"key":"c","text":"Sea water"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"IS 456 permits water fit for drinking (potable) for mixing and curing. It should be free of harmful oils, acids, alkalis, salts and organic matter, with pH ≥ 6.","marks":1,"source":{"kind":"past","set":5,"question":41,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q41 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-05-042","src":"PAST-05-042","text":"In a roof truss, the value of snow load is taken as","options":[{"key":"a","text":"3.5 N/m<sup>2</sup>"},{"key":"b","text":"4.5 N/m<sup>2</sup>"},{"key":"c","text":"1.5 N/m<sup>2</sup>"},{"key":"d","text":"2.5 N/m<sup>2</sup>"}],"answer":"d","explanation":"IS 875 (Part 4) takes the snow load as about 2.5 N per m<sup>2</sup> per mm depth of snow on a horizontal surface. It is reduced for roof slopes above \\(10^\\circ\\) and neglected beyond \\(50^\\circ\\).","marks":1,"source":{"kind":"past","set":5,"question":42,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q42 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-05-043","src":"PAST-05-043","text":"Shear reinforcement is provided in an RC section to","options":[{"key":"a","text":"Counteract maximum BM"},{"key":"b","text":"Counteract negative moment at support"},{"key":"c","text":"Counteract crack and shear failure"},{"key":"d","text":"None of these"}],"answer":"c","explanation":"Stirrups and bent-up bars resist the diagonal tension caused by shear. They control inclined cracking and prevent brittle shear failure.","marks":1,"source":{"kind":"past","set":5,"question":43,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q43 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-05-061","src":"PAST-05-061","text":"In a non-parallel system of seismic design, 100% of the design seismic force in one direction and X% of the design seismic force in the orthogonal direction is considered. The value of X is","options":[{"key":"a","text":"10"},{"key":"b","text":"20"},{"key":"c","text":"30"},{"key":"d","text":"40"}],"answer":"c","explanation":"IS 1893 combines 100% of the design seismic force in one direction with 30% in the orthogonal direction (the 100% + 30% rule).","marks":2,"source":{"kind":"past","set":5,"question":61,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q61 · 2 marks"},"topic":"ACiE0501"},{"id":"PAST-05-072","src":"PAST-05-072","text":"How can you strengthen a wall of 50 m length and 5 m height built with brick masonry?","options":[{"key":"a","text":"By constructing buttresses"},{"key":"b","text":"By using stronger brick"},{"key":"c","text":"By using stronger grade of mortar"},{"key":"d","text":"It can't be strengthened"}],"answer":"a","explanation":"A long, tall wall is weak in lateral stability. Buttresses (piers) at intervals stiffen it and cut its effective length, which stronger bricks or mortar alone cannot do.","marks":2,"source":{"kind":"past","set":5,"question":72,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q72 · 2 marks"},"topic":"ACiE0506"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-05-001","src":"PAST-05-001","text":"The ratio of COD to BOD of untreated sewage is","options":[{"key":"a","text":"1.25-1.5"},{"key":"b","text":"2.5-5"},{"key":"c","text":"5-10"},{"key":"d","text":"None of these"}],"answer":"a","explanation":"COD oxidises both biodegradable and non-biodegradable organics, so it always exceeds BOD<sub>5</sub>. For fresh domestic sewage the ratio is typically about 1.25-1.5 (BOD to COD about 0.7-0.8); higher ratios point to poorly biodegradable waste.","marks":1,"source":{"kind":"past","set":5,"question":1,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q1 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-05-006","src":"PAST-05-006","text":"Blue baby syndrome is caused due to","options":[{"key":"a","text":"Nitrate"},{"key":"b","text":"Nitrite"},{"key":"c","text":"Chloride"},{"key":"d","text":"Sulphate"}],"answer":"a","explanation":"Excess nitrate in drinking water (limit 45 mg/L as NO<sub>3</sub>) causes methaemoglobinaemia in infants. Nitrate is reduced to nitrite in the gut, which converts haemoglobin to methaemoglobin.","marks":1,"source":{"kind":"past","set":5,"question":6,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q6 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-05-022","src":"PAST-05-022","text":"A disease which is widespread and can reach globally is termed as","options":[{"key":"a","text":"Epidemic"},{"key":"b","text":"Endemic"},{"key":"c","text":"Pandemic"},{"key":"d","text":"Hyper-endemic"}],"answer":"c","explanation":"A pandemic is an epidemic that spreads across countries and continents. An epidemic is a sudden outbreak within a community or region, and an endemic disease is constantly present in an area. The source key gives (a), but global spread defines a pandemic.","marks":1,"source":{"kind":"past","set":5,"question":22,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q22 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-05-036","src":"PAST-05-036","text":"What is the main objective of toxicity assessment?","options":[{"key":"a","text":"To determine source of pathway"},{"key":"b","text":"To determine chemical concentration"},{"key":"c","text":"To estimate how much of a substance does what kind of harm"},{"key":"d","text":"To analyse chemical exposure"}],"answer":"c","explanation":"Toxicity (dose–response) assessment establishes how much of a substance causes what kind of harmful effect. Exposure assessment deals with pathways and concentrations.","marks":1,"source":{"kind":"past","set":5,"question":36,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q36 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-05-037","src":"PAST-05-037","text":"Use of chlorine in water does not reduce","options":[{"key":"a","text":"Ammonia"},{"key":"b","text":"Organic matter"},{"key":"c","text":"Iron"},{"key":"d","text":"Dissolved oxygen"}],"answer":"d","explanation":"Chlorine is an oxidant: it reacts with ammonia (forming chloramines), organic matter and ferrous iron, and those reactions make up the chlorine demand. It does not remove dissolved oxygen.","marks":1,"source":{"kind":"past","set":5,"question":37,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q37 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-05-040","src":"PAST-05-040","text":"The reserve of water for the breakdown period is generally not more than …… of total storage.","options":[{"key":"a","text":"15%"},{"key":"b","text":"25%"},{"key":"c","text":"30%"},{"key":"d","text":"50%"}],"answer":"b","explanation":"The breakdown (emergency) reserve kept in a service reservoir for pump failure or repairs is generally limited to about 25% of the total storage.","marks":1,"source":{"kind":"past","set":5,"question":40,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q40 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-05-055","src":"PAST-05-055","text":"Alum is chemically","options":[{"key":"a","text":"Copper sulphate"},{"key":"b","text":"Aluminium sulphate"},{"key":"c","text":"Ferrous sulphate"},{"key":"d","text":"Ferric sulphate"}],"answer":"b","explanation":"Filter alum is hydrated aluminium sulphate, Al<sub>2</sub>(SO<sub>4</sub>)<sub>3</sub>·18H<sub>2</sub>O, the most common coagulant.","marks":1,"source":{"kind":"past","set":5,"question":55,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q55 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-05-075","src":"PAST-05-075","text":"The efficiency of chlorine as a disinfectant","options":[{"key":"a","text":"increases with pH increasing"},{"key":"b","text":"decreases with pH increasing"},{"key":"c","text":"is maximum at pH 7"},{"key":"d","text":"remains constant at all pH"}],"answer":"b","explanation":"Hypochlorous acid (HOCl) is about 80 times more effective than the hypochlorite ion. It dominates below pH 7.5 and dissociates to \\(\\text{OCl}^-\\) as the pH rises, so efficiency falls with increasing pH.","marks":2,"source":{"kind":"past","set":5,"question":75,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q75 · 2 marks"},"topic":"ACiE0603"},{"id":"PAST-05-079","src":"PAST-05-079","text":"If a 2% solution of a sewage sample is incubated for 5 days at 20°C and the depletion of oxygen was found to be 5 ppm, the B.O.D. of the sewage is","options":[{"key":"a","text":"200 ppm"},{"key":"b","text":"225 ppm"},{"key":"c","text":"250 ppm"},{"key":"d","text":"None of these"}],"answer":"c","explanation":"BOD is the DO depletion divided by the dilution fraction: \\[\\text{BOD} = \\dfrac{5}{0.02} = 250\\ \\text{ppm}\\]","marks":2,"source":{"kind":"past","set":5,"question":79,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q79 · 2 marks"},"topic":"ACiE0605"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-05-014","src":"PAST-05-014","text":"Due to a lined channel section","options":[{"key":"a","text":"Water logging increases"},{"key":"b","text":"Cross sectional area increases"},{"key":"c","text":"Command area increases"},{"key":"d","text":"All of these"}],"answer":"c","explanation":"Lining cuts seepage losses, reducing waterlogging, and lowers roughness, so a smaller section carries the flow. The water saved and the higher attainable water level increase the command area.","marks":1,"source":{"kind":"past","set":5,"question":14,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q14 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-05-032","src":"PAST-05-032","text":"The structure provided to discharge extra water from a canal is","options":[{"key":"a","text":"canal regulator"},{"key":"b","text":"canal fall"},{"key":"c","text":"canal outlet"},{"key":"d","text":"canal escape"}],"answer":"d","explanation":"A canal escape is a safety valve that releases surplus water from the canal into a natural drain, protecting the banks from overtopping.","marks":1,"source":{"kind":"past","set":5,"question":32,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q32 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-05-033","src":"PAST-05-033","text":"The structure at the head of a regulator to remove silt is","options":[{"key":"a","text":"Silt ejector"},{"key":"b","text":"Silt excluder"},{"key":"c","text":"Silt extractor"},{"key":"d","text":"All of these"}],"answer":"b","explanation":"A silt excluder is built in the river bed just upstream of the head regulator so that silt-laden bottom water is passed through the undersluices. Silt ejectors (extractors) are placed in the canal a short distance downstream.","marks":1,"source":{"kind":"past","set":5,"question":33,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q33 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-05-034","src":"PAST-05-034","text":"A launching apron is made of","options":[{"key":"a","text":"Stone masonry"},{"key":"b","text":"Brick masonry"},{"key":"c","text":"Gabion"},{"key":"d","text":"Concrete"}],"answer":"c","explanation":"A launching apron must be flexible enough to settle into the scour hole and armour the slope. It is made of loose boulders or gabions (wire crates of stone), never rigid masonry or concrete.","marks":1,"source":{"kind":"past","set":5,"question":34,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q34 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-05-035","src":"PAST-05-035","text":"Saline soil can be improved by","options":[{"key":"a","text":"Leaching"},{"key":"b","text":"Pyrite application"},{"key":"c","text":"Gypsum application"},{"key":"d","text":"Lime application"}],"answer":"a","explanation":"Saline soils carry excess soluble salts, which are removed by leaching with good-quality water through drains. Gypsum or pyrite is used for sodic (alkali) soils.","marks":1,"source":{"kind":"past","set":5,"question":35,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q35 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-05-056","src":"PAST-05-056","text":"Bligh's theory of seepage assumes","options":[{"key":"a","text":"equal weightage to the horizontal and vertical creep"},{"key":"b","text":"more weightage to horizontal creep than vertical creep"},{"key":"c","text":"less weightage to horizontal creep than vertical creep"},{"key":"d","text":"loss of head follows the sine curve"}],"answer":"a","explanation":"Bligh's creep theory treats every metre of creep length, horizontal or vertical, alike, with the head lost uniformly along it. Lane's weighted creep gives horizontal creep one-third weight, and Khosla's theory gives curved head-loss variation.","marks":1,"source":{"kind":"past","set":5,"question":56,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q56 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-05-071","src":"PAST-05-071","text":"A broad crested weir (\\(C_w = 1.5\\)) having length 30 m and height 2.5 m is placed across a river having RL of upstream bed 1080 m. If the discharge passing the weir is 90 m<sup>3</sup>/s, find the RL of the flood wall (take free board as 1.2 m).","options":[{"key":"a","text":"1085.28 m"},{"key":"b","text":"1084.08 m"},{"key":"c","text":"1081.58 m"},{"key":"d","text":"1083.70 m"}],"answer":"a","explanation":"The head over the weir is \\[\\begin{aligned} H &amp;= \\left(\\dfrac{Q}{C_wL}\\right)^{2{/}3} = \\left(\\dfrac{90}{45}\\right)^{2{/}3} \\\\ &amp;= 1.587\\ \\text{m} \\end{aligned}\\] The flood level is \\[\\begin{aligned} &amp;1080 + 2.5 + 1.587 \\\\ &amp;= 1084.09\\ \\text{m} \\end{aligned}\\] and adding the 1.2 m freeboard gives the wall top at about RL 1085.28 m.","marks":2,"source":{"kind":"past","set":5,"question":71,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q71 · 2 marks"},"topic":"ACiE0703"},{"id":"PAST-05-074","src":"PAST-05-074","text":"What should be the length of weir for a 50 year design flood of 4000 m<sup>3</sup>/s, if the bank to bank width of the river is 280 m?","options":[{"key":"a","text":"270 m"},{"key":"b","text":"280 m"},{"key":"c","text":"290 m"},{"key":"d","text":"300 m"}],"answer":"b","explanation":"Lacey's waterway is \\[\\begin{aligned} P &amp;= 4.75\\sqrt{Q} = 4.75\\sqrt{4000} \\\\ &amp;\\approx 300\\ \\text{m} \\end{aligned}\\] This exceeds the bank-to-bank width, so the weir length is limited to the river width, 280 m.","marks":2,"source":{"kind":"past","set":5,"question":74,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q74 · 2 marks"},"topic":"ACiE0703"},{"id":"PAST-05-076","src":"PAST-05-076","text":"A barrage of 400 m length is designed across an alluvial river. The U/S and D/S lengths of the proposed guide banks of this barrage will be about","options":[{"key":"a","text":"400 m and 100 m"},{"key":"b","text":"450 m and 150 m"},{"key":"c","text":"500 m and 100 m"},{"key":"d","text":"600 m and 200 m"}],"answer":"c","explanation":"Guide banks usually extend 1.0-1.5 L upstream and 0.2-0.4 L downstream. The key takes \\[1.25L = 500\\ \\text{m}\\] \\[0.25L = 100\\ \\text{m}\\] upstream and downstream respectively.","marks":2,"source":{"kind":"past","set":5,"question":76,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q76 · 2 marks"},"topic":"ACiE0704"},{"id":"PAST-05-077","src":"PAST-05-077","text":"What is the consumptive use for a crop in the month of April having a consumptive use coefficient equal to 0.80, if the pan evaporation is 35 cm?","options":[{"key":"a","text":"28.00 cm"},{"key":"b","text":"43.75 cm"},{"key":"c","text":"35.80 cm"},{"key":"d","text":"40.80 cm"}],"answer":"a","explanation":"The consumptive use is \\(k\\) times the pan evaporation: \\[C_u = 0.80 \\times 35 = 28\\ \\text{cm}\\]","marks":2,"source":{"kind":"past","set":5,"question":77,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q77 · 2 marks"},"topic":"ACiE0701"}]},{"name":"Hydropower","questions":[{"id":"PAST-05-012","src":"PAST-05-012","text":"The flow duration curve at a given head of a hydroelectric plant is used to determine","options":[{"key":"a","text":"total power available at the site"},{"key":"b","text":"total units of energy available"},{"key":"c","text":"load factor at the plant"},{"key":"d","text":"diversity factor for the plant"}],"answer":"a","explanation":"At a known head, power ∝ Q, so the flow duration curve becomes a power duration curve. It shows the power available at the site for any percentage of time, including the firm power.","marks":1,"source":{"kind":"past","set":5,"question":12,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q12 · 1 mark"},"topic":"ACiE0802"},{"id":"PAST-05-029","src":"PAST-05-029","text":"A Kaplan turbine is","options":[{"key":"a","text":"Inward flow impulse turbine"},{"key":"b","text":"Outward flow reaction turbine"},{"key":"c","text":"Low head axial flow turbine"},{"key":"d","text":"High head mixed flow turbine"}],"answer":"c","explanation":"A Kaplan is an axial-flow reaction turbine with adjustable runner blades. It suits low heads and large discharges.","marks":1,"source":{"kind":"past","set":5,"question":29,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q29 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-05-030","src":"PAST-05-030","text":"The function of a surge tank is to","options":[{"key":"a","text":"Supply water at constant pressure"},{"key":"b","text":"Relieve water hammer pressures in the penstock pipe"},{"key":"c","text":"Produce surge in the pipeline"},{"key":"d","text":"None of the above"}],"answer":"b","explanation":"The surge tank provides a free water surface near the turbine. It absorbs the pressure rise on load rejection and supplies water on load demand, protecting the penstock (and the headrace tunnel) from water hammer.","marks":1,"source":{"kind":"past","set":5,"question":30,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q30 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-05-031","src":"PAST-05-031","text":"On the basis of hydraulic design, dams are classified as","options":[{"key":"a","text":"diversion and detention dams"},{"key":"b","text":"storage and diversion dams"},{"key":"c","text":"overflow and non-overflow dams"},{"key":"d","text":"arch and buttress dams"}],"answer":"c","explanation":"By hydraulic design, dams are overflow (spillway) or non-overflow. The function-based classes are storage, diversion and detention, and the structural classes are gravity, arch and buttress.","marks":1,"source":{"kind":"past","set":5,"question":31,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q31 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-05-057","src":"PAST-05-057","text":"A penstock in a hydroelectric power plant is","options":[{"key":"a","text":"a pipe connected to runner outlet"},{"key":"b","text":"a nozzle that releases high pressure water on turbine blades"},{"key":"c","text":"a conduit connecting forebay to scroll case of turbine"},{"key":"d","text":"a pipe connecting surge tank to dam"}],"answer":"c","explanation":"The penstock is the pressure pipe that carries water from the forebay (or surge tank) down to the turbine scroll casing. The pipe at the runner outlet is the draft tube.","marks":1,"source":{"kind":"past","set":5,"question":57,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q57 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-05-068","src":"PAST-05-068","text":"If the total hydroelectric potential of a plant is 84 GW, convert the potential into energy considering a load factor of 60%.","options":[{"key":"a","text":"441 TWh"},{"key":"b","text":"735 TWh"},{"key":"c","text":"1226 TWh"},{"key":"d","text":"504 TWh"}],"answer":"a","explanation":"The annual energy is \\[\\begin{aligned} E &amp;= 84 \\times 8760 \\times 0.60 \\\\ &amp;= 441{,}504\\ \\text{GWh} \\\\ &amp;\\approx 441\\ \\text{TWh} \\end{aligned}\\] with the power in GW and the year as 8760 h.","marks":2,"source":{"kind":"past","set":5,"question":68,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q68 · 2 marks"},"topic":"ACiE0802"}]},{"name":"Transportation","questions":[{"id":"PAST-05-013","src":"PAST-05-013","text":"What is the standard temperature for the Marshall stability test?","options":[{"key":"a","text":"27°C"},{"key":"b","text":"25°C"},{"key":"c","text":"60°C"},{"key":"d","text":"40°C"}],"answer":"c","explanation":"Marshall specimens are soaked and tested at 60°C, the critical high service temperature of bituminous pavements. Penetration and ductility tests use 25°C and 27°C.","marks":1,"source":{"kind":"past","set":5,"question":13,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q13 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-05-024","src":"PAST-05-024","text":"Which roller is used for compacting clayey soils?","options":[{"key":"a","text":"Vibratory"},{"key":"b","text":"Smooth wheeled"},{"key":"c","text":"Sheep footed"},{"key":"d","text":"Pneumatic tyred"}],"answer":"c","explanation":"The projecting feet of a sheepsfoot roller knead and compact cohesive (clayey) soils from the bottom of the layer upwards.","marks":1,"source":{"kind":"past","set":5,"question":24,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q24 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-05-025","src":"PAST-05-025","text":"One of the probable causes of rutting on flexible pavements is","options":[{"key":"a","text":"excessive stripping of binder material from the wearing course"},{"key":"b","text":"use of flaky aggregates in the wearing course"},{"key":"c","text":"inadequate compaction of pavement layers"},{"key":"d","text":"high wind speeds"}],"answer":"c","explanation":"Rutting is permanent deformation in the wheel paths. It comes mainly from further densification and shear flow of layers that were inadequately compacted (and from soft mixes and heavy traffic).","marks":1,"source":{"kind":"past","set":5,"question":25,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q25 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-05-026","src":"PAST-05-026","text":"Which of the following is used for speed regulation?","options":[{"key":"a","text":"98th percentile cumulative frequency"},{"key":"b","text":"75th percentile cumulative frequency"},{"key":"c","text":"50th percentile cumulative frequency"},{"key":"d","text":"85th percentile cumulative frequency"}],"answer":"d","explanation":"The 85th percentile spot speed is used to set the upper (regulatory) speed limit. The 98th percentile is used as the geometric design speed and the 15th percentile as the lower limit.","marks":1,"source":{"kind":"past","set":5,"question":26,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q26 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-05-049","src":"PAST-05-049","text":"According to NRRS, an arterial road is called","options":[{"key":"a","text":"Path"},{"key":"b","text":"Marga"},{"key":"c","text":"Sadak"},{"key":"d","text":"Upamarga"}],"answer":"a","explanation":"In the Nepali road naming hierarchy used here, arterial (through) roads are called Path, and sub-arterial, collector and local roads carry the lower-order names (Sadak, Marga, Upamarga).","marks":1,"source":{"kind":"past","set":5,"question":49,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q49 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-05-058","src":"PAST-05-058","text":"The relationship between SSD and ISD is","options":[{"key":"a","text":"\\(\\mathrm{SSD} = \\mathrm{ISD}\\)"},{"key":"b","text":"\\(\\mathrm{SSD} = 1.5\\,\\mathrm{SSD}\\)"},{"key":"c","text":"\\(\\mathrm{SSD} = \\mathrm{ISD} + \\mathrm{OSD}\\)"},{"key":"d","text":"\\(\\mathrm{SSD} = 2\\,\\mathrm{ISD}\\)"}],"answer":"d","explanation":"Intermediate sight distance is taken as twice the stopping sight distance: \\[\\text{ISD} = 2\\,\\text{SSD}\\] The key marks (d), whose printed wording reverses this relation.","marks":1,"source":{"kind":"past","set":5,"question":58,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q58 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-05-059","src":"PAST-05-059","text":"An enoscope is used to determine","options":[{"key":"a","text":"spot speed"},{"key":"b","text":"average speed"},{"key":"c","text":"travel time"},{"key":"d","text":"none of these"}],"answer":"a","explanation":"An enoscope (mirror box) makes the observer's line of sight perpendicular to the road over a short base, so vehicles' spot speeds can be timed.","marks":1,"source":{"kind":"past","set":5,"question":59,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q59 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-05-070","src":"PAST-05-070","text":"If the penetration grade is 62, the penetration value is ….","options":[{"key":"a","text":"62 mm"},{"key":"b","text":"6.2 mm"},{"key":"c","text":"0.62 mm"},{"key":"d","text":"620 mm"}],"answer":"b","explanation":"Penetration is expressed in units of 0.1 mm, so grade 62 means the needle penetrated \\[62 \\times 0.1 = 6.2\\ \\text{mm}\\]","marks":2,"source":{"kind":"past","set":5,"question":70,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q70 · 2 marks"},"topic":"ACiE0903"},{"id":"PAST-05-080","src":"PAST-05-080","text":"If the length of a transition curve to be introduced between a straight and a circular curve of radius 500 m is 90 m, the maximum perpendicular offset for the transition curve is","options":[{"key":"a","text":"0.70 m"},{"key":"b","text":"1.70 m"},{"key":"c","text":"2.70 m"},{"key":"d","text":"3.70 m"}],"answer":"c","explanation":"The offset at the end of the transition is \\[\\dfrac{L^2}{6R} = \\dfrac{90^2}{6 \\times 500} = 2.70\\ \\text{m}\\] This is four times the shift \\(\\dfrac{L^2}{24R} = 0.675\\) m.","marks":2,"source":{"kind":"past","set":5,"question":80,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q80 · 2 marks"},"topic":"ACiE0902"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-05-016","src":"PAST-05-016","text":"A solid having an equilateral triangle as base and other faces converging towards its axis is","options":[{"key":"a","text":"Prism"},{"key":"b","text":"Pyramid"},{"key":"c","text":"Hexahedron"},{"key":"d","text":"Cone"}],"answer":"b","explanation":"A pyramid has a polygonal base with triangular faces meeting at the apex on its axis. A triangular base gives a triangular pyramid.","marks":1,"source":{"kind":"past","set":5,"question":16,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q16 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-05-019","src":"PAST-05-019","text":"Which method of project planning was invented first?","options":[{"key":"a","text":"Bar chart"},{"key":"b","text":"Milestone chart"},{"key":"c","text":"CPM"},{"key":"d","text":"PERT"}],"answer":"a","explanation":"Henry Gantt developed the bar chart around 1917. Milestone charts were an improvement on it, and CPM and PERT followed in 1957–58.","marks":1,"source":{"kind":"past","set":5,"question":19,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q19 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-05-020","src":"PAST-05-020","text":"Which engineer is registered in category A?","options":[{"key":"a","text":"General Engineer"},{"key":"b","text":"Professional Engineer"},{"key":"c","text":"Foreign Engineer"},{"key":"d","text":"All of them"}],"answer":"a","explanation":"NEC registers General Engineers in category A, Professional Engineers in category B and Foreign Engineers in category C.","marks":1,"source":{"kind":"past","set":5,"question":20,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q20 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-05-021","src":"PAST-05-021","text":"What is the requirement for being chairman of NEC?","options":[{"key":"a","text":"Bachelor degree and engineering experience of 10 years"},{"key":"b","text":"Bachelor degree and engineering experience of 15 years"},{"key":"c","text":"Master degree and engineering experience of 15 years"},{"key":"d","text":"Master degree and engineering experience of 10 years"}],"answer":"b","explanation":"The chairperson of the Nepal Engineering Council must hold at least a bachelor's degree in engineering and have at least 15 years of engineering experience.","marks":1,"source":{"kind":"past","set":5,"question":21,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q21 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-05-023","src":"PAST-05-023","text":"In incremental analysis, which project is selected as the base alternative?","options":[{"key":"a","text":"Project having lower investment"},{"key":"b","text":"Project having higher investment"},{"key":"c","text":"Any one of these"},{"key":"d","text":"None of these"}],"answer":"a","explanation":"Alternatives are ranked by first cost. The lowest-investment acceptable project is the base (defender), and each higher-cost alternative is justified only if its increment earns at least the MARR.","marks":1,"source":{"kind":"past","set":5,"question":23,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q23 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-05-060","src":"PAST-05-060","text":"The ratio obtained by dividing 'quick assets' by current liabilities is called","options":[{"key":"a","text":"Turnover ratio"},{"key":"b","text":"Acid test ratio"},{"key":"c","text":"Solvency ratio"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"The acid test (quick) ratio is quick assets (current assets less inventory and prepaid items) divided by current liabilities: \\[\\text{QR} = \\dfrac{\\text{quick assets}}{\\text{current liabilities}}\\] About 1 to 1 is considered satisfactory.","marks":1,"source":{"kind":"past","set":5,"question":60,"marks":1,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q60 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-05-063","src":"PAST-05-063","text":"If the rate of interest is 4% for the first year, 5% for the second year and 6% for the third year, then the compound interest on Rs 10,000 for 3 years, if interest is compounded annually, is","options":[{"key":"a","text":"Rs 1580.25"},{"key":"b","text":"Rs 1575.20"},{"key":"c","text":"Rs 1500.00"},{"key":"d","text":"Rs 1570.50"}],"answer":"b","explanation":"The amount is \\[\\begin{aligned} A &amp;= 10{,}000 \\times 1.04 \\\\ &amp;\\quad \\times 1.05 \\times 1.06 \\\\ &amp;= \\text{Rs } 11{,}575.20 \\end{aligned}\\] so the compound interest is Rs 1,575.20.","marks":2,"source":{"kind":"past","set":5,"question":63,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q63 · 2 marks"},"topic":"AALL1002"},{"id":"PAST-05-073","src":"PAST-05-073","text":"If part of the contract work is assigned to another party, it is called","options":[{"key":"a","text":"Sub-contracting"},{"key":"b","text":"Joint venture"},{"key":"c","text":"Both"},{"key":"d","text":"None of these"}],"answer":"a","explanation":"Sub-contracting assigns a portion of the work to another firm, while the main contractor stays responsible to the client. A joint venture is a partnership formed to bid for and execute the whole contract.","marks":2,"source":{"kind":"past","set":5,"question":73,"marks":2,"date":"2080 Mangsir 24","shift":"3rd shift","reference":"Past Paper Set 5, Q73 · 2 marks"},"topic":"AALL1004"}]}]};
